  .byte $1B, $FF, $01, $9D, $20, $1C, $1F, $FE ;-D-- 1EBA6 EB96: 1B FF 01 9D 20 1C 1F FE
DrawHudNames:                     ; DrawFighterNames with A = 0
  LDA #$00                        ;C--S 1EBAE EB9E: A9 00
DrawFighterNames:                 ; queues the names of both fighters (fighterChar, TEXT_END-ended lists indexed by CHAR_*) at FighterNamePpuAddr[fighter*2 + A]: A = 0 the HUD names (FighterNamesHud, $2065 / $2072), A = 4 FighterNames at $2584 / $25F7 (FightVsScreen)
  STA ptr_01                      ;C--S 1EBB0 EBA0: 85 01
  LDX #$01                        ;C--- 1EBB2 EBA2: A2 01
  STX thisFighter                 ;C--- 1EBB4 EBA4: 86 A8
@loop:
  LDX thisFighter                 ;C-J- 1EBB6 EBA6: A6 A8
  LDA fighterChar,X               ;C--- 1EBB8 EBA8: B5 A2
  STA ptr_00                      ;C--- 1EBBA EBAA: 85 00
  TXA                             ;C--- 1EBBC EBAC: 8A
  ASL A                           ;C--- 1EBBD EBAD: 0A
  ADC ptr_01                      ;C--- 1EBBE EBAE: 65 01
  TAX                             ;C--- 1EBC0 EBB0: AA
  LDA FighterNamePpuAddr,X        ;C--- 1EBC1 EBB1: BD 53 EC
  LDY FighterNamePpuAddr+1,X      ;C--- 1EBC4 EBB4: BC 54 EC
  JSR PpuQueueStartRow            ;C--- 1EBC7 EBB7: 20 6B D2
  LDA ptr_01                      ;C--- 1EBCA EBBA: A5 01
  BNE @skip                       ;C--- 1EBCC EBBC: D0 23
  LDY #$00                        ;C--- 1EBCE EBBE: A0 00
  LDA ptr_00                      ;C--- 1EBD0 EBC0: A5 00
  BEQ @loop3                      ;C--- 1EBD2 EBC2: F0 0D
@loop2:
  INY                             ;C-J- 1EBD4 EBC4: C8
  LDA FighterNamesHud,Y           ;C--- 1EBD5 EBC5: B9 01 EC
  CMP #TEXT_END                   ;C--- 1EBD8 EBC8: C9 FF
  BNE @loop2                      ;C--- 1EBDA EBCA: D0 F8
  INY                             ;C--- 1EBDC EBCC: C8
  DEC ptr_00                      ;C--- 1EBDD EBCD: C6 00
  BNE @loop2                      ;C--- 1EBDF EBCF: D0 F3
@loop3:
  LDA FighterNamesHud,Y           ;C-J- 1EBE1 EBD1: B9 01 EC
  JSR PpuQueuePutX                ;C--- 1EBE4 EBD4: 20 5F D2
  INY                             ;C--- 1EBE7 EBD7: C8
  CMP #TEXT_END                   ;C--- 1EBE8 EBD8: C9 FF
  BNE @loop3                      ;C--- 1EBEA EBDA: D0 F5
@loop4:
  DEC thisFighter                 ;C-J- 1EBEC EBDC: C6 A8
  BPL @loop                       ;C--- 1EBEE EBDE: 10 C6
  RTS                             ;C--- 1EBF0 EBE0: 60
@skip:
  LDY #$00                        ;C-J- 1EBF1 EBE1: A0 00
  LDA ptr_00                      ;C--- 1EBF3 EBE3: A5 00
  BEQ @loop6                      ;C--- 1EBF5 EBE5: F0 0D
@loop5:
  INY                             ;C-J- 1EBF7 EBE7: C8
  LDA FighterNames,Y              ;C--- 1EBF8 EBE8: B9 2A EC
  CMP #TEXT_END                   ;C--- 1EBFB EBEB: C9 FF
  BNE @loop5                      ;C--- 1EBFD EBED: D0 F8
  INY                             ;C--- 1EBFF EBEF: C8
  DEC ptr_00                      ;C--- 1EC00 EBF0: C6 00
  BNE @loop5                      ;C--- 1EC02 EBF2: D0 F3
@loop6:
  LDA FighterNames,Y              ;C-J- 1EC04 EBF4: B9 2A EC
  JSR PpuQueuePutX                ;C--- 1EC07 EBF7: 20 5F D2
  INY                             ;C--- 1EC0A EBFA: C8
  CMP #TEXT_END                   ;C--- 1EC0B EBFB: C9 FF
  BNE @loop6                      ;C--- 1EC0D EBFD: D0 F5
  BEQ @loop4                      ;C--- 1EC0F EBFF: F0 DB
FighterNamesHud:                  ; by CHAR_*, TEXT_END-ended; tiles of the small HUD font (charmap hud; only the letters the seven names need, K = $60), drawn by DrawHudNames
  CHARMAP_HUD
  .byte "LEO", TEXT_END           ;-D-- 1EC11 EC01: -EC04
  .byte "RAPH", TEXT_END          ;-D-- 1EC15 EC05: -EC09
  .byte "MIKE", TEXT_END          ;-D-- 1EC1A EC0A: -EC0E
  .byte "DON", TEXT_END           ;-D-- 1EC1F EC0F: -EC12
  .byte "CASEY", TEXT_END         ;-D-- 1EC23 EC13: -EC18
  .byte "HOTHEAD", TEXT_END       ;-D-- 1EC29 EC19: -EC20
  .byte "SHREDDER", TEXT_END      ;-D-- 1EC31 EC21: -EC29
  CHARMAP_ASCII
FighterNames:                     ; by CHAR_*: tile numbers of the DrawText font minus $80 (charmap bgm); the glyphs sit in tiles $00-$3F of the 2 KB CHR bank R0 = $7E that the IRQ band of the VS screen (name row + VS logo) selects (Mesen: swapping R0 $7E breaks the names and the logo, R0 $22 etc. do not)
  CHARMAP_BGM
  .byte "LEO", TEXT_END           ;-D-- 1EC3A EC2A: -EC2D
  .byte "RAPH", TEXT_END          ;-D-- 1EC3E EC2E: -EC32
  .byte "MIKE", TEXT_END          ;-D-- 1EC43 EC33: -EC37
  .byte "DON", TEXT_END           ;-D-- 1EC48 EC38: -EC3B
  .byte "CASEY", TEXT_END         ;-D-- 1EC4C EC3C: -EC41
  .byte "HOTHEAD", TEXT_END       ;-D-- 1EC52 EC42: -EC49
  .byte "SHREDDER", TEXT_END      ;-D-- 1EC5A EC4A: -EC52
  CHARMAP_ASCII
FighterNamePpuAddr:               ; big-endian PPU addresses by fighter*2 + A of DrawFighterNames
  .dbyt $2065                     ;-D-- 1EC63 EC53: 20 65
  .dbyt $2072                     ;-D-- 1EC65 EC55: 20 72
  .dbyt $2584                     ;-D-- 1EC67 EC57: 25 84
  .dbyt $25F7                     ;-D-- 1EC69 EC59: 25 F7
